if (!p8 && p8Path) {
  try {
    p8 = (await fsPromises.readFile(p8Path, 'utf8')).trim();
  } catch (error) {
    console.warn('[APNs] Failed to read OPENCHAMBER_APNS_P8_PATH:', error?.message ?? error);
